import React, { useState } from 'react';
import './CSS/NewArrivals.css';

const newArrivalsData = [
  {
    id: 1,
    name: 'Pro Max 16 Ultra',
    tagline: 'Next-Gen AI & Camera Tech',
    price: 1299,
    release: 'This Week',
    badge: 'JUST LAUNCHED',
    image: 'https://via.placeholder.com/220x220?text=Phone+16'
  },
  {
    id: 2,
    name: 'Spatial Audio Pods Pro',
    tagline: 'Adaptive Noise Cancellation',
    price: 249,
    release: 'This Week',
    badge: 'NEW',
    image: 'https://via.placeholder.com/220x220?text=Audio+Pods'
  },
  {
    id: 3,
    name: 'Titanium Smartwatch Series 9',
    tagline: '7-Day Battery & ECG Monitor',
    price: 399,
    release: 'This Month',
    badge: 'PRE-ORDER',
    image: 'https://via.placeholder.com/220x220?text=Smartwatch'
  },
  {
    id: 4,
    name: 'Foldable Vision Pad',
    tagline: 'Ultra-thin Dual OLED Screen',
    price: 1599,
    release: 'This Month',
    badge: 'NEW',
    image: 'https://via.placeholder.com/220x220?text=Foldable+Pad'
  },
  {
    id: 5,
    name: 'MagCharge Power Bank 15W',
    tagline: 'Wireless Snap-On Charging',
    price: 59,
    release: 'This Week',
    badge: 'JUST LAUNCHED',
    image: 'https://via.placeholder.com/220x220?text=MagCharge'
  },
  {
    id: 6,
    name: 'Pro Gaming Controller Wireless',
    tagline: 'Haptic Feedback & Zero Latency',
    price: 149,
    release: 'This Month',
    badge: 'NEW',
    image: 'https://via.placeholder.com/220x220?text=Controller'
  }
];

const NewArrivals = () => {
  const [filter, setFilter] = useState('All');

  const filteredData = filter === 'All' 
    ? newArrivalsData 
    : newArrivalsData.filter(item => item.release === filter);

  return (
    <div className='new-arrivals-page'>
      {/* Header Banner */}
      <div className='arrivals-header'>
        <span className='arrivals-tag'>LATEST RELEASES</span>
        <h1>Fresh Tech & New Drops</h1>
        <p>Explore the newest smartphones, wearable devices, and high-performance gadgets added to HEXCART.</p>
      </div>

      {/* Filter Tabs */}
      <div className='arrivals-filter-bar'>
        {['All', 'This Week', 'This Month'].map((tab) => (
          <button
            key={tab}
            className={`arrivals-tab ${filter === tab ? 'active' : ''}`}
            onClick={() => setFilter(tab)}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Product Grid */}
      <div className='arrivals-grid'>
        {filteredData.map((item) => (
          <div key={item.id} className='arrival-card'>
            <div className='card-img-container'>
              <span className='release-badge'>{item.badge}</span>
              <img src={item.image} alt={item.name} />
            </div>

            <div className='card-details'>
              <span className='release-time'><i className="fa-regular fa-clock"></i> {item.release}</span>
              <h3 className='item-name'>{item.name}</h3>
              <p className='item-tagline'>{item.tagline}</p>

              <div className='card-bottom'>
                <span className='item-price'>${item.price}</span>
                <button className='buy-now-btn'>Shop Now</button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default NewArrivals;
